const routes={workspace:'执行记录',journal:'交易日志',performance:'表现与复盘',playbook:'执行规则',data:'数据与备份'};
let loaded=loadStorage(),state=loaded.state,storageError=loaded.error,selectedId=null,journalFilter='all',journalSymbol='all',performanceSymbol='all',draftTimer=null,toastTimer=null,pendingImport=null,saveQueue=Promise.resolve(),busy=false;
const records=()=>state.rounds.filter(r=>r.fills.length);
const round=id=>state.rounds.find(r=>r.id===id);
function empty(title,text){return `<div class="empty-state"><strong>${esc(title)}</strong><p>${esc(text)}</p></div>`;}
function toast(text,error=false){const e=$('#toast');e.textContent=clean(text);e.classList.toggle('error',error);e.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.hidden=true,error?7000:3500);}
function status(text,error=false){$('#save-status').textContent=text;$('#save-status').classList.toggle('error',error);}
function showStorageError(text){storageError=text;status('保存失败',true);$('#storage-alert').hidden=false;$('#storage-alert').innerHTML=`<strong>${esc(text)}</strong> <button id="reload-data" class="quiet-button">重新载入</button> <button id="download-raw" class="quiet-button">下载本机原始数据</button>`;}
async function commit(change,{backup=true,render=true}={}){
  clearTimeout(draftTimer);let writing=false;
  const task=saveQueue.then(async()=>{
    if(!state||storageError)throw Error(storageError||'请先恢复本机数据。');
    const next=structuredClone(state);change(next);validateState(next);status('保存中…');writing=true;
    const saved=await saveStorage(next,state.revision,{backup});
    if(!backup)saved.draft=structuredClone(state.draft);
    state=saved;status('已保存至本机');if(render)renderAll();return saved;
  });
  saveQueue=task.catch(e=>{if(writing||e instanceof DataConflict)showStorageError(e.message);});
  return task;
}
function hydrate(){
  if(!state)return;const d=state.draft,f=$('#buy-form');
  d.symbol??='SOXL';d.quantity??=d.plan.quantity??(Number(d.plan.entry)>0?Math.floor(Number(d.plan.amount)/Number(d.plan.entry)):'');
  f.elements.price.value=d.plan.entry;f.elements.qty.value=d.quantity;f.elements.reason.value=d.reason;f.elements.equity.value=d.plan.equity;f.elements.at.value=nowInput();
  readDraft();renderSymbols();
}
function readDraft(){
  if(!state)return;const f=$('#buy-form'),d=state.draft,exit=executionPrices(d.symbol,f.elements.price.value);
  d.quantity=f.elements.qty.value;d.sizingMode='shares';d.reason=f.elements.reason.value;
  Object.assign(d.plan,{entry:f.elements.price.value,quantity:d.quantity,amount:tradeAmount(d.quantity,f.elements.price.value)??'',equity:f.elements.equity.value,stop:exit?.stop??'',targetMode:'r',targetR:2,targetPrice:'',costs:0,gapPct:0});
}
function scheduleDraft(){if(!state||storageError)return;readDraft();renderBuy();clearTimeout(draftTimer);draftTimer=setTimeout(()=>commit(()=>{},{backup:false,render:false}).catch(e=>toast(e.message,true)),450);status('草稿待保存');}
function renderSymbols(){const symbol=state?.draft.symbol??'SOXL';$$('[data-symbol]').forEach(b=>{b.classList.toggle('selected',b.dataset.symbol===symbol);b.setAttribute('aria-pressed',String(b.dataset.symbol===symbol));});$('#active-symbol-name').textContent=symbol;$('#active-symbol-leverage').textContent=SYMBOLS[symbol].leverage;$('#reference-symbol').textContent=symbol;}
function buyInput(){const v=values($('#buy-form'));return {...v,symbol:state.draft.symbol,at:iso(v.at)};}
function renderBuy(){
  const symbol=state?.draft.symbol??'SOXL',f=$('#buy-form'),exit=executionPrices(symbol,f.elements.price.value),profile=EXECUTION_PROFILES[symbol];
  const qty=Number(f.elements.qty.value),amount=tradeAmount(qty,f.elements.price.value),equity=Number(f.elements.equity.value),portfolio=state?portfolioRisk(state):{valid:false,risk:0},risk=exit&&amount!==null?qty*(exit.entry-exit.stop):null;
  $('#home-equity').textContent=money(equity,0);
  $('#exit-reference').innerHTML=`<div class="exit-price-card"><span>−1R 止损参考 <small>−${pct(profile.stopPct)}</small></span><strong id="auto-stop">${price(exit?.stop??null)}</strong></div><div class="exit-price-card"><span>+2R 全部退出 <small>+${pct(profile.stopPct*2)}</small></span><strong id="auto-target">${price(exit?.target??null)}</strong></div>`;
  $('#buy-numbers').innerHTML=[['投入金额',money(amount)],['本笔初始 1R',money(risk)],['本笔风险／权益',risk!==null&&equity>0?pct(risk/equity):'—'],['账户 1% 预算',equity>0?money(equity*.01):'—'],['已有主动仓位风险',portfolio.valid?money(portfolio.risk):'未知'],['记录后合计风险',portfolio.valid&&risk!==null?money(portfolio.risk+risk):'—']].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('');
  $('#buy-override').hidden=true;$('#save-buy').disabled=!!storageError;
  if(!exit){$('#buy-alert').textContent='填入买入价，即可看到两档退出参考价。';return;}
  const violations=[];
  if(risk!==null&&equity>0){if(amount>equity+1e-8)violations.push('投入金额超过账户权益。');if(risk>equity*.01+1e-8)violations.push('本笔风险超过账户权益 1%。');if(!portfolio.valid)violations.push('已有持仓风险未知，不能确认共同预算。');else if(portfolio.risk+risk>equity*.01+1e-8)violations.push('记录后主动仓位合计风险超过账户权益 1%。');}
  if(state){const g=tradingGuard(state);if(g.blocked)violations.push(...g.reasons);}
  $('#buy-override').hidden=!violations.length;
  $('#buy-alert').innerHTML=violations.length?`<strong class="negative">本次记录存在规则偏离</strong><ul>${[...new Set(violations)].map(v=>'<li>'+esc(clean(v))+'</li>').join('')}</ul>`:risk===null?'股数填写后自动核对金额和账户共同风险。':'<strong>金额与风险已核对</strong><p>保存真实买入；退出价与初始 1R 随本笔记录冻结。</p>';
}
function renderGuard(){
  const g=tradingGuard(state),curve=statistics(state).snapshots;
  $('#guard-panel').innerHTML=g.blocked?`<div class="guard-banner danger"><div><strong>已触发暂停纪律</strong><p>${g.reasons.map(x=>esc(clean(x))).join('<br>')}</p></div><a href="#performance" class="text-link">查看复核 ↗</a></div>`:!curve.latest?'<div class="guard-banner"><div><strong>账户回撤等待权益快照</strong><p>交易记录不等于完整账户权益。录入实际快照后计算回撤。</p></div><a href="#performance" class="text-link">记录快照 ↗</a></div>':'';
}
function card(r){
  const a=accounting(r),c=calculatePlan(r.plan),open=a.qty>0;
  return `<article class="round-card"><div><span class="tag">${r.scope==='history'?'旧持仓历史':open?'持仓中':'已退出'}</span><h3>${esc(r.symbol)}</h3><p>${esc(date(a.entryAt??r.createdAt))} · ${r.fills.length} 笔成交</p>${r.scope==='active'&&!r.executionModel?'<span class="tag">旧退出规则保留</span>':''}</div><div class="round-values"><div><span>剩余股数</span><strong>${a.qty}</strong></div><div><span>成本均价</span><strong>${price(a.avg)}</strong></div><div><span>已实现盈亏 / R</span><strong class="${cls(a.realized)}">${money(a.realized)}</strong><small>${rval(a.r)}</small></div></div><div class="journal-actions">${open?`<button class="primary-button" data-sell="${esc(r.id)}">记录卖出</button>`:''}<button class="quiet-button" data-open-record="${esc(r.id)}">详情／复盘 ↗</button></div>${open?`<div class="position-exits"><span>当前止损参考 <strong>${price(Number.isFinite(effectiveStop(r))?effectiveStop(r):null)}</strong></span><span>退出参考 <strong>${price(c.valid?c.target:null)}</strong></span><span>未实现盈亏 <strong class="${cls(a.unrealized)}">${money(a.unrealized)}</strong></span></div>`:''}</article>`;
}
function renderHome(){const rs=records(),s=statistics(state);$('#open-positions').innerHTML=rs.filter(r=>r.scope==='active'&&accounting(r).qty>0).map(card).join('')||empty('还没有主动持仓','登记真实买入后，在这里查看退出参考并记录卖出。');$('#home-stats').innerHTML=[['累计已实现盈亏',money(s.realized)],['已退出交易',String(s.total)],['胜率',pct(s.winRate)],['最大账户回撤',s.snapshots.latest?pct(s.snapshots.maxDD):'—']].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('');$('#recent-records').innerHTML=rs.slice().sort((a,b)=>Date.parse(b.fills.at(-1).at)-Date.parse(a.fills.at(-1).at)).slice(0,3).map(card).join('')||empty('还没有成交记录','不填入示例盈利，先记录你的真实成交。');}
function renderJournal(){const symbols=[...new Set([...Object.keys(SYMBOLS),...records().map(r=>r.symbol)])];$('#journal-symbol').innerHTML='<option value="all">全部标的</option>'+symbols.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');$('#journal-symbol').value=journalSymbol;$$('#journal-filters button').forEach(b=>b.classList.toggle('selected',b.dataset.filter===journalFilter));const list=records().filter(r=>journalSymbol==='all'||r.symbol===journalSymbol).filter(r=>journalFilter==='all'||journalFilter==='history'&&r.scope==='history'||r.scope==='active'&&(journalFilter==='open'&&accounting(r).qty>0||journalFilter==='closed'&&accounting(r).closed)).sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));$('#journal-list').innerHTML=list.map(card).join('')||empty('这个分类还没有成交','不同买入独立记录，旧持仓与主动统计隔离。');}
function renderChart(curve){
  if(!curve.latest){$('#equity-chart').innerHTML=empty('权益曲线等待真实快照','初始资金规则不是账户历史，尚无数据计算最大回撤。');return;}
  const ps=curve.points,w=920,h=210,pad=30,lo=Math.min(...ps.map(p=>p.normalized)),hi=Math.max(...ps.map(p=>p.normalized)),range=hi-lo||Math.max(100,hi*.04),min=lo-range*.1,max=hi+range*.1;
  const points=ps.map((p,i)=>[pad+i*(w-pad*2)/Math.max(1,ps.length-1),pad+(max-p.normalized)/(max-min)*(h-pad*2)]),line=points.map(([x,y],i)=>(i?'L':'M')+x.toFixed(2)+','+y.toFixed(2)).join(' ');
  $('#equity-chart').innerHTML=`<svg class="equity-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="账户权益曲线"><title>出入金调整后的权益，最大回撤 ${pct(curve.maxDD)}</title>${[0,.5,1].map(t=>{const y=pad+t*(h-pad*2);return `<line x1="${pad}" x2="${w-pad}" y1="${y}" y2="${y}" stroke="var(--line)"/>`;}).join('')}<path d="${line}" fill="none" stroke="var(--accent)" stroke-width="2"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="3" fill="var(--accent)"><title>${esc(date(ps[i].at))} · ${money(ps[i].normalized)} · 回撤 ${pct(ps[i].drawdown)}</title></circle>`).join('')}</svg>`;
}
function renderPerformance(){const s=statistics(state,performanceSymbol);$('#sample-warning').innerHTML=s.sampleInsufficient?`<div class="sample-warning"><strong>样本不足</strong> · 当前 ${s.total} 笔已退出交易，不能据此宣称稳定胜率或预计年化收益。</div>`:'';$('#performance-stats').innerHTML=[['累计已实现盈亏',money(s.realized),'含真实部分退出'],['胜率',pct(s.winRate),`${s.total} 笔已退出`],['平均盈利 R',rval(s.avgWinR),'冻结的初始 1R'],['平均亏损 R',rval(s.avgLossR),'亏损 R 的绝对值'],['实际盈亏比',s.payoff===null?'—':s.payoff.toFixed(2),'平均盈利金额 / 平均亏损金额'],['每笔期望',money(s.expectancy),'已退出交易的平均结果'],['平均 R',rval(s.expectancyR),'已退出且有初始风险'],['最大账户回撤',s.snapshots.latest?pct(s.snapshots.maxDD):'—','出入金调整后的快照'],['连续亏损',String(s.streak),`最长 ${s.maxStreak} 笔`],['规则遵守率',pct(s.compliance),`${s.reviewCount} 笔明确自评`]].map(([k,v,n])=>`<article class="stat-card"><span>${k}</span><strong>${v}</strong><small>${n}</small></article>`).join('');renderChart(s.snapshots);$('#closed-records').innerHTML=s.closed.slice().reverse().map(x=>card(x.round)).join('')||empty('还没有已退出交易','胜率和期望只按真实完整退出统计。');$('#snapshot-list').innerHTML=state.snapshots.length?`<div class="table-wrap"><table><thead><tr><th>中国时间</th><th class="num">总权益</th><th class="num">净出入金</th><th></th></tr></thead><tbody>${state.snapshots.slice().reverse().map(x=>`<tr><td>${esc(date(x.at))}</td><td class="num">${money(x.equity)}</td><td class="num">${money(x.flow)}</td><td><button class="table-action" data-snapshot="${esc(x.id)}">更正</button><button class="table-action" data-delete-snapshot="${esc(x.id)}">删除</button></td></tr>`).join('')}</tbody></table></div>`:empty('没有权益快照','按实际账户权益补录，避免把单笔交易盈亏当成账户表现。');$('#drawdown-review-list').innerHTML=state.drawdownReviews.map(r=>`<p class="snapshot-note">${esc(date(r.at))} · ${esc(r.notes)}</p>`).join('');}
function renderData(){if(state){const rs=records(),unused=state.rounds.length-rs.length;$('#data-summary').innerHTML=`${rs.length} 笔交易 · ${rs.reduce((s,r)=>s+r.fills.length,0)} 次成交 · ${state.snapshots.length} 条权益快照<br>最近写入：${state.meta.updatedAt?esc(date(state.meta.updatedAt)):'尚未写入'}${unused?'<br>'+unused+' 条旧版未成交档案保留在备份中':''}`;$('#account-start-date').value=state.settings.startDate;}else $('#data-summary').textContent='本机原始数据读取异常，请恢复备份。';$('#backup-list').innerHTML=localBackups().map((b,i)=>`<div class="backup-item"><div>版本 ${esc(b.revision)}<small>${esc(date(b.at))}</small></div><button class="quiet-button" data-backup-download="${i}">下载</button><button class="quiet-button" data-backup-restore="${i}">恢复</button></div>`).join('')||empty('还没有本机滚动备份','正式修改时自动保留上一版。');}
